def encode(string):
    vowels = {'a': '1', 'e': '2', 'i': '3', 'o': '4', 'u': '5'}
    result = []
    for char in string:
        if char in vowels:
            result.append(vowels[char])
        else:
            result.append(char)
    return "".join(result)

def decode(string):
    vowels = {'1': 'a', '2': 'e', '3': 'i', '4': 'o', '5': 'u'}
    result = []
    for char in string:
        result.append(vowels.get(char, char))
    return "".join(result)
